import json
with open('/app/resources/treasury_bulletin_1940_03.json', 'r') as f:
    data = json.load(f)

# Search through the JSON structure
def search_json(obj, path=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if 'exchange' in key.lower() or 'pound' in key.lower() or 'dollar' in key.lower() or 'rate' in key.lower():
                print(f'{path}.{key}: {value}')
            search_json(value, f'{path}.{key}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):  # Limit search
            search_json(item, f'{path}[{i}]')

search_json(data)
